export default function Faq() {
  const [activeAccordion, setActiveAccordion] = useState(null);

  const toggleAccordion = (id) => {
    if (activeAccordion === id) {
      setActiveAccordion(null);
    } else {
      setActiveAccordion(id);
    }
  };

  return (
    <div className="min-h-screen bg-blue-900 text-slate-600 p-8 sm:p-12">
      {/* Decorative Top Gradient Header */}
      <div className="relative h-48 sm:h-64">
        <div className="absolute top-0 left-0 right-0 bottom-0 bg-gradient-to-br from-blue-700 to-slate-800 opacity-20" />
        <div className="absolute inset-0 bg-black opacity-60" />
        <div className="relative flex items-end justify-center p-8 text-center sm:p-12">
          <div className="w-full max-w-md text-center sm:max-w-2xl">
            <h1 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-600 sm:text-5xl">
              Frequently Asked Questions
            </h1>
            <p className="mt-4 text-slate-600">Get answers to common inquiries about our legal services.</p>
          </div>
        </div>
      </div>

      {/* Main FAQ Section */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="space-y-12">
          {faqItems.map((item) => (
            <div key={item.id} className="relative overflow-hidden rounded-2xl bg-slate-100 p-6 shadow-2xl transition-all duration-300 hover:shadow-blue-500/10">
              <div className="absolute -top-12 -right-12 -left-12 -bottom-12 bg-slate-100 border border-slate-200 rounded-2xl" />

              <div className="relative flex items-start justify-between p-4 pb-6 sm:p-6">
                <div className="flex items-start">
                  <div className="flex-shrink-0">
                    <ShieldCheck className="w-5 h-5 text-blue-400" />
                  </div>
                  <div className="ml-3 min-w-0 flex-1 pt-0.5">
                    <h4 className="text-sm font-medium text-slate-600 tracking-wide">
                      {item.title}
                    </h4>
                    <div className="mt-2 text-sm text-slate-500">{item.content}</div>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => toggleAccordion(item.id)}
                  className="inline-flex items-center rounded-lg bg-slate-100 px-3 py-2 text-slate-600 hover:text-slate-600 hover:bg-slate-100"
                >
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>

              {activeAccordion === item.id && (
                <div className="animate-fade-in duration-500 p-6">
                  <div className="space-y-4">
                    {/* Accordion Expansion Animation */}
                    <div className="relative -mx-6 -my-6 bg-slate-100 rounded-2xl border border-slate-200 p-6 transition-all duration-300 hover:border-slate-200">
                      {item.content}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

.font-display { font-family: 'Libre Baskerville', Georgia, serif; }
.font-body { font-family: 'Source Sans 3', system-ui, sans-serif; }
body { font-family: 'Source Sans 3', system-ui, sans-serif; }

@keyframes reveal-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
.reveal { opacity: 0; }
.reveal-visible { animation: reveal-up 0.8s cubic-bezier(0.22, 1, 0.36, 1) both; }
@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; }
  .reveal-visible { animation: none; }
}
@keyframes fade-up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up { animation: fade-up 0.7s ease-out both; }
@keyframes float-slow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.animate-marquee { animation: marquee 30s linear infinite; }

